from collections import deque

def comps(mat,val):
 coords=set(map(tuple,np.argwhere(mat==val))); result=[]
 while coords:
  st=[coords.pop()]; cc=[]
  while st:
   p=st.pop(); cc.append(p)
   for q in [(p[0]+1,p[1]),(p[0]-1,p[1]),(p[0],p[1]+1),(p[0],p[1]-1)]:
    if q in coords: coords.remove(q); st.append(q)
  result.append(sorted(cc))
 return result
